                reservation.price().subtotal(),
                reservation.price().discount(),
                reservation.price().total(),
                buildText(reservation, room));
    }

    private static String titleFor(GuestType guestType) {
        return switch (guestType) {
            case INDIVIDUAL -> "Comprovante de reserva";
            case COMPANY -> "Fatura de hospedagem";
            case FOREIGN -> "Booking receipt";
        };
    }

    private static String buildText(Reservation reservation, Room room) {
        Guest guest = reservation.guest();
        return switch (guest.type()) {
            case INDIVIDUAL -> buildIndividualReceipt(reservation, room);
            case COMPANY -> buildCompanyInvoice(reservation, room);
            case FOREIGN -> buildForeignReceipt(reservation, room);
        };
    }

    private static String buildIndividualReceipt(Reservation reservation, Room room) {
        StringBuilder text = new StringBuilder();
        text.append("Comprovante de reserva nº ").append(reservation.id()).append('\n');
        text.append("Hóspede: ").append(reservation.guest().name())
                .append(" (CPF ").append(reservation.guest().cpf()).append(")\n");
