        text.append("Nights: ").append(EnglishFormat.money(reservation.price().subtotal())).append('\n');
        if (reservation.price().discount().signum() > 0) {
            text.append("Discount: ").append(EnglishFormat.money(reservation.price().discount())).append('\n');
        }
        text.append("Total: ").append(EnglishFormat.money(reservation.price().total())).append('\n');
        return text.toString();
    }
}

